SELECT n.Nm, InNames = CASE WHEN EXISTS (SELECT 1 FROM dbo.HS_Team_Names t WHERE t.Team_Name = n.Nm) THEN 1 ELSE 0 END
FROM (VALUES ('Church Hill (TN)'),('Winchester (TN)'),('Dickson (TN)'),('Rhea Central (TN)'),('McMinnville Central (TN)'),('Lynnville (TN)'),('Martin (TN)'),('Copperhill (TN)'),('Ashland City (TN)'),('Tiptonville (TN)'),('Englewood (TN)'),('Nashville Pearl (TN)'),('Selmer (TN)'),('Newbern (TN)'),('Wartrace (TN)'),('St. Andrews Academy (TN)'),('Gatlinburg-Pittman (TN)'),('Jackson Old Hickory Academy (TN)'),('Fayetteville Central (TN)'),('Somerville Fayette Academy (TN)')) n(Nm);
